// feed-data.js
//
// Reads series + episodes from Supabase (read only) and turns them into
// the same "slide" shape app.js already knows how to render. No writes,
// no coin/unlock logic here — that stays fake/frontend-only for now.

// Generic cover art used when a series has no cover_image_url yet.
// These are two of the mockup's original placeholder photos (the ones
// with no series-specific text baked into them). The third original
// placeholder (the hand-drawn "MIDNIGHT HEIR" SVG) is NOT reused here
// because it has that series' title and tagline drawn directly into
// the artwork, so it would be wrong to show it under a different title.
const PLACEHOLDER_ART = [
  {type:'img', src:'data:image/jpeg;base64,'},
  {type:'img', src:'data:image/jpeg;base64,'},
];

// Fetches all series and their episodes, and returns an array of slide
// objects shaped exactly like the mockup's old hardcoded `slides` array.
//
// For now (no logged-in user / no progress tracking yet), each series
// is represented by its first episode, and `progress`, `liked`, `saved`
// are neutral/false. Coin cost and unlock state stay fake/frontend-only,
// same as before this change — they are NOT derived from the database.
async function fetchSlides() {
  try {
    const { data: seriesRows, error: seriesError } = await supabaseClient
      .from('series')
      .select('id, title, description, cover_image_url, free_episode_count, created_at, featured_at');

    if (seriesError) throw seriesError;
    if (!seriesRows || seriesRows.length === 0) return [];

    const { data: episodeRows, error: episodesError } = await supabaseClient
      .from('episodes')
      .select('id, series_id, episode_number, title, bunny_video_id, duration_seconds')
      .order('episode_number', { ascending: true });

    if (episodesError) throw episodesError;

    const episodesBySeries = {};
    (episodeRows || []).forEach(ep => {
      if (!episodesBySeries[ep.series_id]) episodesBySeries[ep.series_id] = [];
      episodesBySeries[ep.series_id].push(ep);
    });

    const slides = seriesRows
      .map((series, i) => {
        const episodes = episodesBySeries[series.id] || [];
        if (episodes.length === 0) return null;

        const firstEpisode = episodes[0];
        const totalEp = episodes.length;
        const currentEp = firstEpisode.episode_number;
        const nextEp = Math.min(currentEp + 1, totalEp);

        return {
          id: series.id,
          createdAt: series.created_at,
          featuredAt: series.featured_at,
          title: series.title,
          synopsis: series.description || '',
          epBadge: 'EP ' + currentEp + ' · ' + totalEp,
          progress: 0,
          currentEp: currentEp,
          totalEp: totalEp,
          nextEp: nextEp,
          likes: '0',
          saved: false,
          liked: false,
          coinCost: 2,
          art: series.cover_image_url
            ? { type: 'img', src: series.cover_image_url }
            : PLACEHOLDER_ART[i % PLACEHOLDER_ART.length]
        };
      })
      .filter(Boolean);

    return slides;
  } catch (err) {
    console.error('Narrava: failed to load feed data from Supabase', err);
    return [];
  }
}

// Fetches the full genre list, for the Discover screen's Categories tab.
async function fetchGenres() {
  try {
    const { data, error } = await supabaseClient
      .from('genres')
      .select('id, name');
    if (error) throw error;
    return data || [];
  } catch (err) {
    console.error('Narrava: failed to load genres from Supabase', err);
    return [];
  }
}

// Fetches the series <-> genre links, for filtering the Categories tab.
async function fetchSeriesGenres() {
  try {
    const { data, error } = await supabaseClient
      .from('series_genres')
      .select('series_id, genre_id');
    if (error) throw error;
    return data || [];
  } catch (err) {
    console.error('Narrava: failed to load series_genres from Supabase', err);
    return [];
  }
}
